// 事業内容と決算情報の検索結果を統合
const businessData = $input.all()[0].json;
const earningsData = $input.all()[1].json;

// 検索結果のテキストを結合
let combinedBodyText = '';

// 事業内容の回答と結果を追加
combinedBodyText += '=== 事業内容 ===\n';
if (businessData.answer) {
  combinedBodyText += businessData.answer + '\n\n';
}
if (businessData.results) {
  businessData.results.forEach((result, index) => {
    combinedBodyText += `--- ソース ${index + 1}: ${result.title} ---\n`;
    combinedBodyText += result.content + '\n\n';
    if (result.raw_content) {
      combinedBodyText += result.raw_content.substring(0, 2000) + '\n\n';
    }
  });
}

// 決算情報の回答と結果を追加
combinedBodyText += '\n=== 決算情報 ===\n';
if (earningsData.answer) {
  combinedBodyText += earningsData.answer + '\n\n';
}
if (earningsData.results) {
  earningsData.results.forEach((result, index) => {
    combinedBodyText += `--- ソース ${index + 1}: ${result.title} ---\n`;
    combinedBodyText += result.content + '\n\n';
    if (result.raw_content) {
      combinedBodyText += result.raw_content.substring(0, 2000) + '\n\n';
    }
  });
}

// ソースURLを収集
const sources = [];
if (businessData.results) {
  businessData.results.forEach(r => sources.push({ title: r.title, url: r.url }));
}
if (earningsData.results) {
  earningsData.results.forEach(r => sources.push({ title: r.title, url: r.url }));
}

return {
  combinedBodyText,
  sources: JSON.stringify(sources),
  ticker: $('企業情報を設定').item.json.ticker,
  companyName: $('企業情報を設定').item.json.companyName,
  companyNameJa: $('企業情報を設定').item.json.companyNameJa,
  outputDir: $('企業情報を設定').item.json.outputDir,
  businessAnswer: businessData.answer || '',
  earningsAnswer: earningsData.answer || ''
};

// 要約内容にメタデータを追加
const summary = $input.item.json.summaryContent;
const ticker = $input.item.json.ticker;
const companyName = $input.item.json.companyName;
const sources = JSON.parse($input.item.json.sources || '[]');
const now = new Date().toISOString();

// ソース一覧を生成
let sourceList = '';
if (sources.length > 0) {
  sourceList = '\n## 参照ソース\n\n';
  sources.forEach((s, i) => {
    sourceList += `${i + 1}. [${s.title}](${s.url})\n`;
  });
}

// メタデータヘッダーを追加
const header = `---
ticker: ${ticker}
company: ${companyName}
generated_at: ${now}
type: research_summary
---

`;

// フッターを追加
const footer = `\n\n---\n\n*この要約は ${now.split('T')[0]} に自動生成されました。*\n*投資判断は自己責任でお願いします。*\n`;

const finalContent = header + summary + sourceList + footer;

return {
  content: finalContent,
  fileName: $input.item.json.fileName,
  outputDir: $input.item.json.outputDir,
  ticker: ticker,
  companyName: companyName
};
